 "content": "def transform(grid):
    """Add a smaller hollow 5-rectangle inside the 5-rectangle, with a 2 band."""
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    if not points:
        return out
    top = min(r for r, _ in points)
    bottom = max(r for r, _ in points)
    left = min(c for _, c in points)
    right = max(c for _, c in points)
    # Color the original frame's interior, then make a nested hollow frame.
    for r in range(top + 1, bottom):
        for c in range(left + 1, right):
            out[r][c] = 2
    t, b, l, rr = top + 2, bottom - 2, left + 2, right - 2
    if t < b and l < rr:
        for c in range(l, rr + 1):
            out[t][c] = out[b][c] = 5
        for r in range(t, b + 1):
            out[r][l] = out[r][rr] = 5
        for r in range(t + 1, b):
            for c in range(l + 1, rr):
                out[r][c] = 0
