 "content": "def transform(grid):
    """Create a centered nested 5-frame and color its surrounding band 2."""
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    if not points:
        return out
    top, bottom = min(r for r, _ in points), max(r for r, _ in points)
    left, right = min(c for _, c in points), max(c for _, c in points)
    # Inset by one quarter of the outer frame's span (rounded down).
    dr = max(1, (bottom - top) // 4)
    dc = max(1, (right - left) // 4)
    for r in range(top + 1, bottom):
        for c in range(left + 1, right):
            out[r][c] = 2
    t, b, l, rr = top + dr, bottom - dr, left + dc, right - dc
    for c in range(l, rr + 1):
        out[t][c] = out[b][c] = 5
    for r in range(t, b + 1):
        out[r][l] = out[r][rr] = 5
    for r in range(t + 1, b):
        for c in range(l + 1, rr):
            out[r][c] = 0
    return out
